class PaymentSession {
  mode: 'started' | 'authorized' | 'captured' = 'started'

  process(payment: Payment) {
    if (this.mode === 'started') return this.authorize(payment)
    if (this.mode === 'authorized') return this.capture(payment)
    if (this.mode === 'captured') return this.noop()
  }

  authorize(p: Payment) {}
